DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.update_recurring_task(uuid,text,date,text,uuid,uuid)'::regprocedure) INTO f; f:=replace(f,'IF t.id IS NULL OR NOT activity_can_read(cp.id)', 'IF t.status IN(''not_started'',''in_progress'') AND (p.month+interval ''1 month'')::date<=(now() AT TIME ZONE ''Asia/Kolkata'')::date AND t.due_date<(now() AT TIME ZONE ''Asia/Kolkata'')::date THEN t.status:=''missed_review''; END IF; IF t.id IS NULL OR NOT activity_can_read(cp.id)'); f:=replace(f,'IF _due IS NOT NULL OR _status=''closed''', 'IF t.status=''missed_review'' AND _due IS NULL AND _status<>''closed'' THEN RAISE EXCEPTION ''Head must reschedule or close missed tasks with a reason''; END IF; IF _due IS NOT NULL OR _status=''closed'''); EXECUTE f; SELECT pg_get_functiondef('public.department_scorecards(date)'::regprocedure) INTO f; f:=replace(f,'LEFT JOIN client_tasks t ON t.assignee_id=pm.user_id','LEFT JOIN (SELECT assignee_id,due_date,status,done_at,client_id,launch_id FROM client_tasks UNION ALL SELECT rt.owner_id,rt.original_due_date,CASE WHEN rt.status=''superseded'' THEN ''not_applicable'' ELSE rt.status END,rt.done_at,cp.client_id,(SELECT l.id FROM client_launches l WHERE l.client_id=cp.client_id AND l.status IN(''active'',''live'',''offboarding'') ORDER BY l.created_at DESC LIMIT 1) FROM recurring_tasks rt JOIN activity_plans ap ON ap.id=rt.plan_id JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id) t ON t.assignee_id=pm.user_id'); EXECUTE f; END $$;